66	
67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
78	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
84	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
90	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
91	
92	    /** Request header carrying the client-supplied idempotency key for owner creation. */
93	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
94	
95	    /**
96	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
97	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
98	     * creating a duplicate, making owner creation idempotent with respect to the key.
99	     */
100	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
101	
102	    private final ClinicService clinicService;
103	
104	    private final OwnerMapper ownerMapper;
105	
106	    private final PetMapper petMapper;
107	
108	    private final VisitMapper visitMapper;
109	
110	    public OwnerRestControllerV1(ClinicService clinicService,
111	                                 OwnerMapper ownerMapper,
112	                                 PetMapper petMapper,
113	                                 VisitMapper visitMapper) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        List<OwnerDto> ownerDtos = owners.stream()
133	            .map(this::toOwnerDtoWithBulkWarning)
134	            .toList();
135	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        String idempotencyKey = currentIdempotencyKey();
152	        if (idempotencyKey != null) {
153	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
154	            if (existingId != null) {
155	                Owner existing = this.clinicService.findOwnerById(existingId);
156	                if (existing != null) {
157	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
158	                }
159	            }
160	        }
161	        List<String> missingFields = new ArrayList<>();
162	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
163	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
164	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
165	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
166	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
167	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
168	        String normalizedAddress = hasStructuredAddress
169	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
170	            : normalizedFlatAddress;
171	        requireNonBlank(missingFields, "address", normalizedAddress);
172	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
173	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
174	        if (!missingFields.isEmpty()) {
175	            throw new MissingRequiredFieldsException(missingFields);
176	        }
177	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
178	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
179	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
180	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
181	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
182	        requireDailyLimitNotReached(registrationDate);
183	        requireCityBelowCapacity(ownerFieldsDto.getCity());
184	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
185	        ownerFieldsDto.setTelephone(normalizedTelephone);
186	        if (ownerFieldsDto.getEmail() != null) {
187	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
188	        }
189	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
190	        HttpHeaders headers = new HttpHeaders();
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        owner.setAddress(normalizedAddress);
193	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
194	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
195	            ? normalizedAddressLine2 : null);
196	        owner.setRegistrationDate(registrationDate);
197	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
198	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
199	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
200	        requireUniqueIdentity(owner);
201	        requireNoHouseholdDuplicate(owner, sharesHousehold);
202	        markPossibleDuplicate(owner, sharesHousehold);
203	        this.clinicService.saveOwner(owner);
204	        if (idempotencyKey != null) {
205	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
206	        }
207	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
208	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
209	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
210	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
215	
216	    /**
217	     * Returns the {@code Idempotency-Key} header of the request in progress, or {@code null} when the
218	     * header is absent, blank, or there is no active servlet request. The generated {@link OwnersApi}
219	     * signature carries no header parameter, so it is read from the current request context.
220	     */
221	    private static String currentIdempotencyKey() {
222	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
223	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
224	            if (key != null && !key.isBlank()) {
225	                return key;
226	            }
227	        }
228	        return null;
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner == null) {
236	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	        }
238	        currentOwner.setAddress(ownerFieldsDto.getAddress());
239	        currentOwner.setCity(ownerFieldsDto.getCity());
240	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
241	        currentOwner.setLastName(ownerFieldsDto.getLastName());
242	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
243	        this.clinicService.saveOwner(currentOwner);
244	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
245	    }
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Transactional
249	    @Override
250	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
251	        Owner owner = this.clinicService.findOwnerById(ownerId);
252	        if (owner == null) {
253	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	        }
255	        this.clinicService.deleteOwner(owner);
256	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
262	        Owner owner = this.clinicService.findOwnerById(ownerId);
263	        if (owner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        HttpHeaders headers = new HttpHeaders();
267	        Pet pet = petMapper.toPet(petFieldsDto);
268	        owner.setId(ownerId);
269	        pet.setOwner(owner);
270	        pet.getType().setName(null);
271	        this.clinicService.savePet(pet);
272	        PetDto petDto = petMapper.toPetDto(pet);
273	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
274	            .buildAndExpand(pet.getId()).toUri());
275	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
281	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
282	        if (currentOwner != null) {
283	            Pet currentPet = this.clinicService.findPetById(petId);
284	            if (currentPet != null) {
285	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
286	                currentPet.setName(petFieldsDto.getName());
287	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
288	                this.clinicService.savePet(currentPet);
289	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
290	            }
291	        }
292	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
293	    }
294	
295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Override
297	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
298	        HttpHeaders headers = new HttpHeaders();
299	        Visit visit = visitMapper.toVisit(visitFieldsDto);
300	        Pet pet = new Pet();
301	        pet.setId(petId);
302	        visit.setPet(pet);
303	        this.clinicService.saveVisit(visit);
304	        VisitDto visitDto = visitMapper.toVisitDto(visit);
305	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
306	            .buildAndExpand(visit.getId()).toUri());
307	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
308	    }
309	
310	
311	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
312	    @Override
313	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
314	        Owner owner = this.clinicService.findOwnerById(ownerId);
315	        if (owner != null) {
316	            Pet pet = owner.getPet(petId);
317	            if (pet != null) {
318	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
319	            }
320	        }
321	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
322	    }
323	
324	    /**
325	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
326	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
327	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
328	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
329	     *
330	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
331	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
332	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
333	     * base region-and-hash code is returned unchanged.
334	     *
335	     * @param owner the owner being created, with its region-determining postcode and city populated
336	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
337	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
338	     */
339	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
340	        String region = ownerMapper.toRegion(owner);
341	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
342	        String baseCode = region + "-" + hash8;
343	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
344	            .map(Owner::getCustomerCode)
345	            .filter(java.util.Objects::nonNull)
346	            .collect(java.util.stream.Collectors.toSet());
347	        if (!existingCodes.contains(baseCode)) {
348	            return baseCode;
349	        }
350	        int n = 2;
351	        while (existingCodes.contains(baseCode + "-" + n)) {
352	            n++;
353	        }
354	        return baseCode + "-" + n;
355	    }
356	
357	    /**
358	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
359	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
360	     */
361	    private static String sha256Hex8(String value) {
362	        try {
363	            byte[] digest = MessageDigest.getInstance("SHA-256")
364	                .digest(value.getBytes(StandardCharsets.UTF_8));
365	            StringBuilder sb = new StringBuilder();
366	            for (byte b : digest) {
367	                sb.append(String.format("%02X", b));
368	            }
369	            return sb.substring(0, 8);
370	        }
371	        catch (NoSuchAlgorithmException e) {
372	            throw new IllegalStateException("SHA-256 not available", e);
373	        }
374	    }
375	
376	    /**
377	     * Counts the existing owners (those already persisted before this create) whose first and last
378	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
379	     * the new owner as its {@code namesakeCount} and echoed back on reads.
380	     *
381	     * @param firstName the incoming owner's first name (already validated non-blank)
382	     * @param lastName the incoming owner's last name (already validated non-blank)
383	     * @return the number of existing namesakes sharing both names case-insensitively
384	     */
385	    private int countNamesakes(String firstName, String lastName) {
386	        return (int) this.clinicService.findAllOwners().stream()
387	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
388	                && lastName.equalsIgnoreCase(existing.getLastName()))
389	            .count();
390	    }
391	
392	    /**
393	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
394	     * whitespace-only), so the caller can reject the request listing every offending field.
395	     */
396	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
397	        if (value == null || value.isBlank()) {
398	            missingFields.add(fieldName);
399	        }
400	    }
401	
402	    /**
403	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
404	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
405	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
406	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
407	     * {@code "+61412345678"}.
408	     *
409	     * @param telephone the raw telephone value from the request
410	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
411	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
412	     */
413	    private static String normalizeTelephone(String telephone) {
414	        String e164 = toE164(telephone);
415	        if (e164 == null) {
416	            throw new InvalidFieldValueException("telephone",
417	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
418	        }
419	        return e164;
420	    }
421	
422	    /**
423	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
424	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
425	     * owners' stored numbers when detecting duplicates.
426	     */
427	    private static String toE164(String telephone) {
428	        if (telephone == null) {
429	            return null;
430	        }
431	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
432	        String digits;
433	        if (cleaned.startsWith("+")) {
434	            digits = cleaned.substring(1);
435	        } else {
436	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
437	            digits = "61" + national;
438	        }
439	        if (!digits.matches("[0-9]{8,15}")) {
440	            return null;
441	        }
442	        if (!hasValidNationalLength(digits)) {
443	            return null;
444	        }
445	        return "+" + digits;
446	    }
447	
448	    /**
449	     * Checks the national-number length against the country code for the country codes that pin one.
450	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
451	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
452	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
453	     */
454	    private static boolean hasValidNationalLength(String digits) {
455	        if (digits.startsWith("61")) {
456	            return digits.length() - 2 == 9;
457	        }
458	        if (digits.startsWith("1")) {
459	            return digits.length() - 1 == 10;
460	        }
461	        return true;
462	    }
463	
464	    /**
465	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
466	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
467	     *
468	     * @param email the raw email value from the request (already known to be non-null)
469	     * @return the lower-cased email to be stored and returned
470	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
471	     */
472	    private static String normalizeEmail(String email) {
473	        String trimmed = email.trim();
474	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
475	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
476	        }
477	        String canonical = trimmed.toLowerCase(Locale.ROOT);
478	        String domain = canonical.substring(canonical.indexOf('@') + 1);
479	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
480	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
481	        }
482	        return canonical;
483	    }
484	
485	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
486	    private static final int MAX_OWNERS_PER_CITY = 50;
487	
488	    /**
489	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
490	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
491	     * been validated non-blank.
492	     *
493	     * @param city the incoming owner's city (already validated non-blank)
494	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
495	     */
496	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
497	    private static final int MAX_OWNERS_PER_DAY = 100;
498	
499	    /**
500	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
501	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
502	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
503	     * date rolled forward to a business day), so this caps the number that may be created per day.
504	     *
505	     * @param businessDay the adjusted business-day registration date of the owner being created
506	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
507	     */
508	    /**
509	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
510	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
511	     */
512	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
513	
514	    /**
515	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
516	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
517	     * owner's registration date, otherwise {@code false}.
518	     *
519	     * @param owner the owner to map
520	     * @return the owner DTO with its bulk-signup warning flag populated
521	     */
522	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
523	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
524	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
525	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
526	        ownerDto.setMembershipPoints(points);
527	        ownerDto.setMembershipLevel(OwnerMapper.membershipLevelFor(points));
528	        return ownerDto;
529	    }
530	
531	    /**
532	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
533	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
534	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
535	     * no household.
536	     *
537	     * @param householdId the owner's computed household identifier, or {@code null} when absent
538	     * @return the number of owners in the household
539	     */
540	    private int householdSize(String householdId) {
541	        if (householdId == null) {
542	            return 0;
543	        }
544	        return (int) this.clinicService.findAllOwners().stream()
545	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
546	            .count();
547	    }
548	
549	    /**
550	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
551	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
552	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
553	     */
554	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
555	        if (registrationDate == null) {
556	            return false;
557	        }
558	        long registeredThatDay = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
560	            .count();
561	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
562	    }
563	
564	    private void requireDailyLimitNotReached(LocalDate businessDay) {
565	        long registeredThatDay = this.clinicService.findAllOwners().stream()
566	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
567	            .count();
568	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
569	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
570	        }
571	    }
572	
573	    /**
574	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
575	     * forward, just like a weekend, until it reaches a non-holiday business day.
576	     */
577	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
578	        LocalDate.of(2026, 1, 1),
579	        LocalDate.of(2026, 1, 26),
580	        LocalDate.of(2026, 4, 25),
581	        LocalDate.of(2026, 12, 25),
582	        LocalDate.of(2026, 12, 28));
583	
584	    /**
585	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
586	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
587	     * the effective registration date (whether supplied in the request or defaulted to the server date)
588	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
589	     * from the registration date uses the adjusted date.
590	     *
591	     * @param date the effective registration date (supplied or defaulted), never {@code null}
592	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
593	     */
594	    private static LocalDate toBusinessDay(LocalDate date) {
595	        LocalDate adjusted = date;
596	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
597	            adjusted = adjusted.plusDays(1);
598	        }
599	        return adjusted;
600	    }
601	
602	    /** Whether {@code date} falls on a Saturday or Sunday. */
603	    private static boolean isWeekend(LocalDate date) {
604	        DayOfWeek day = date.getDayOfWeek();
605	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
606	    }
607	
608	    /** Matches a well-formed postcode: exactly four decimal digits. */
609	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
610	
611	    /**
612	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
613	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
614	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
615	     * present here and accepts any well-formed postcode.
616	     */
617	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
618	        "NSW", new int[] {2000, 2099},
619	        "VIC", new int[] {3000, 3099},
620	        "QLD", new int[] {4000, 4099});
621	
622	    /**
623	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
624	     * optional, so the request contract stays backward-compatible). When present it must be exactly
625	     * four digits and, for a city whose region is known, fall within that region's inclusive range
626	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
627	     * postcode. A malformed or out-of-range value is rejected with a 400.
628	     *
629	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
630	     * @param city the owner's city, used to look up the region whose range constrains the postcode
631	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
632	     */
633	    private void validatePostcode(String postcode, String city) {
634	        if (postcode == null) {
635	            return;
636	        }
637	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
638	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
639	        }
640	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
641	        int[] range = REGION_POSTCODES.get(region);
642	        if (range == null) {
643	            return;
644	        }
645	        int value = Integer.parseInt(postcode);
646	        if (value < range[0] || value > range[1]) {
647	            throw new InvalidFieldValueException("postcode",
648	                "Postcode must be valid for the city's region " + region);
649	        }
650	    }
651	
652	    /**
653	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
654	     * date defaults to the server date). When present it must not be later than the current server
655	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
656	     *
657	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
658	     * @throws InvalidFieldValueException if the supplied date is later than the server date
659	     */
660	    private void validateRegistrationDate(LocalDate registrationDate) {
661	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
662	            throw new InvalidFieldValueException("registrationDate",
663	                "Registration date must not be later than the current date");
664	        }
665	    }
666	
667	    private void requireCityBelowCapacity(String city) {
668	        long cityOwners = this.clinicService.findAllOwners().stream()
669	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
670	            .count();
671	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
672	            throw new CityAtCapacityException(city);
673	        }
674	    }
675	
676	    /**
677	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
678	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
679	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
680	     * former separate telephone, email and household checks. Because the telephone is part of the
681	     * key, two members of the same household (same {@code householdId}) with different telephones
682	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
683	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
684	     *
685	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
686	     *              already populated
687	     * @throws DuplicateIdentityException if another owner already has this exact identity key
688	     */
689	    private void requireUniqueIdentity(Owner owner) {
690	        String identityKey = ownerMapper.toIdentityKey(owner);
691	        boolean taken = this.clinicService.findAllOwners().stream()
692	            .filter(existing -> !isDeleted(existing))
693	            .map(ownerMapper::toIdentityKey)
694	            .anyMatch(identityKey::equals);
695	        if (taken) {
696	            throw new DuplicateIdentityException(identityKey);
697	        }
698	    }
699	
700	    /**
701	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
702	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
703	     * duplicate is allowed when the only matching owner has been deleted.
704	     */
705	    private static boolean isDeleted(Owner owner) {
706	        return Boolean.TRUE.equals(owner.getDeleted());
707	    }
708	
709	    /**
710	     * Rejects the request when the incoming owner would join an existing household, unless the owner
711	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
712	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
713	     * same {@code householdId} is a member of the same household, so a second such owner is a
714	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
715	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
716	     * so no household key) is never a household duplicate.
717	     *
718	     * @param owner the incoming owner, with its computed {@code householdId} already populated
719	     * @param sharesHousehold whether the request opted in to joining an existing household
720	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
721	     */
722	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
723	        if (sharesHousehold) {
724	            return;
725	        }
726	        String householdId = owner.getHouseholdId();
727	        if (householdId == null) {
728	            return;
729	        }
730	        boolean householdExists = this.clinicService.findAllOwners().stream()
731	            .filter(existing -> !isDeleted(existing))
732	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
733	        if (householdExists) {
734	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
735	        }
736	    }
737	
738	    /**
739	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
740	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
741	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
742	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
743	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
744	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
745	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
746	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
747	     *
748	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
749	     * @param sharesHousehold whether the request opted in as a declared household member
750	     */
751	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
752	        owner.setPossibleDuplicate(false);
753	        owner.setPossibleDuplicateOf(null);
754	        if (sharesHousehold) {
755	            return;
756	        }
757	        String householdId = owner.getHouseholdId();
758	        if (householdId == null) {
759	            return;
760	        }
761	        String telephone = owner.getTelephone();
762	        this.clinicService.findAllOwners().stream()
763	            .filter(existing -> householdId.equals(existing.getHouseholdId())
764	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
765	            .min(java.util.Comparator.comparing(Owner::getId))
766	            .ifPresent(match -> {
767	                owner.setPossibleDuplicate(true);
768	                owner.setPossibleDuplicateOf(match.getId());
769	            });
770	    }
771	
772	    /**
773	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
774	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
775	     * comparisons are case-insensitive.
776	     */
777	    private static String normalizeForHousehold(String value) {
778	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
779	    }
780	
781	    /**
782	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
783	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
784	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
785	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
786	     * value normalizes to the empty string, so the required-field check rejects an address that is
787	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
788	     *
789	     * @param address the raw address value from the request (may be {@code null})
790	     * @return the normalized address, or the empty string when blank after normalization
791	     */
792	    private static String normalizeAddress(String address) {
793	        if (address == null) {
794	            return "";
795	        }
796	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
797	        if (collapsed.isEmpty()) {
798	            return "";
799	        }
800	        String[] tokens = collapsed.split(" ");
801	        StringBuilder sb = new StringBuilder();
802	        for (String token : tokens) {
803	            String expanded = switch (token) {
804	                case "ST" -> "STREET";
805	                case "RD" -> "ROAD";
806	                case "AVE" -> "AVENUE";
807	                default -> token;
808	            };
809	            if (sb.length() > 0) {
810	                sb.append(' ');
811	            }
812	            sb.append(expanded);
813	        }
814	        return sb.toString();
815	    }
816	
817	    /**
818	     * Composes the stored/returned {@code address} from the normalized structured lines: the
819	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
820	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
821	     * normalized via {@link #normalizeAddress(String)}.
822	     *
823	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
824	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
825	     * @return the composed address string
826	     */
827	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
828	        if (normalizedAddressLine2.isEmpty()) {
829	            return normalizedAddressLine1;
830	        }
831	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
832	    }
833	
834	    /**
835	     * Derives the stable household identifier for an owner from its last name and postcode as the
836	     * upper-cased first 12 hex characters of the SHA-256 digest of
837	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
838	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
839	     * identifier is a deterministic function of the normalized last name and postcode, owners that
840	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
841	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
842	     * postcode and there is then nothing to key on.
843	     *
844	     * @param lastName the owner's last name (already validated non-blank)
845	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
846	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
847	     */
848	    private static String householdIdFor(String lastName, String postcode) {
849	        if (postcode == null || postcode.isBlank()) {
850	            return null;
851	        }
852	        String normalizedLastName = normalizeForHousehold(lastName);
853	        try {
854	            byte[] digest = MessageDigest.getInstance("SHA-256")
855	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
856	            StringBuilder sb = new StringBuilder();
857	            for (byte b : digest) {
858	                sb.append(String.format("%02X", b));
859	            }
860	            return sb.substring(0, 12);
861	        }
862	        catch (NoSuchAlgorithmException e) {
863	            throw new IllegalStateException("SHA-256 not available", e);
864	        }
865	    }
866	}
