104	
105	    /**
106	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
107	     */
108	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
109	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
