113	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
114	     */
115	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
116	        "NSW", "Australia/Sydney",
