249	        String digits = telephone.substring(1);
250	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
251	        String countryCode = digits.substring(0, countryCodeLength);
252	        String national = digits.substring(countryCodeLength);
253	        StringBuilder sb = new StringBuilder("+").append(countryCode);
254	        for (int i = 0; i < national.length(); i++) {
