313	     * @return the calendar year in which the date's fiscal year ends
314	     */
315	    static int fiscalYear(LocalDate date) {
316	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
317	    }
318	
319	    /**
320	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
321	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
322	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
323	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
324	     * This qualified mapping cannot observe the owner's household size (which requires counting other
325	     * owners), so it computes the points as if the owner were the only member of its household; the
326	     * controller recomputes the points with the real household size via
327	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
328	     */
329	    @Named("toMembershipPoints")
330	    default Integer toMembershipPoints(Owner owner) {
331	        if (owner == null) {
332	            return null;
333	        }
334	        return membershipPointsFor(owner, 1);
335	    }
336	
337	    /**
338	     * Returns the owner's numeric membership level, derived from its membership points: level
339	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
340	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
341	     * is not observable here and is treated as a single member.
342	     */
343	    @Named("toMembershipLevel")
344	    default Integer toMembershipLevel(Owner owner) {
345	        if (owner == null) {
346	            return null;
347	        }
348	        return membershipLevelFor(membershipPointsFor(owner, 1));
349	    }
350	
351	    /**
352	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
353	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
354	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
355	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
356	     * the {@code registrationDate} and today.
357	     *
358	     * @param owner the owner whose points are computed, never {@code null}
359	     * @param householdSize the number of owners sharing the owner's household
360	     * @return the owner's membership points
361	     */
362	    static int membershipPointsFor(Owner owner, int householdSize) {
363	        int points = 0;
364	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
365	        if (hasEmail) {
366	            points += 2;
367	        }
368	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
369	        if (noNamesakes) {
370	            points += 1;
371	        }
372	        if (householdSize >= 3) {
373	            points += 2;
374	        }
375	        boolean tenured = owner.getRegistrationDate() != null
376	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
377	        if (tenured) {
378	            points += 3;
379	        }
380	        return points;
381	    }
382	
383	    /**
384	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
385	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
386	     *
387	     * @param points the owner's membership points
388	     * @return the corresponding membership level (1-4)
389	     */
390	    static int membershipLevelFor(int points) {
391	        if (points <= 1) {
